/**
 * @brief  UART blocking write function replacement
 * @param  huart: UART handle pointer
 * @param  pData: Pointer to data buffer
 * @param  Size: Amount of data to be sent
 * @param  Timeout: Timeout duration
 * @retval HAL status
 */
HAL_StatusTypeDef UART_WriteBlocking(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size, uint32_t Timeout)
{
  /* Check parameters */
  if ((huart == NULL) || (pData == NULL) || (Size == 0U))
  {
    return HAL_ERROR;
  }

  /* For RECV category (data transmission): Use HAL_BE_Out helper function */
  /* This simulates UART transmission without hardware dependencies */
  HAL_BE_Out(Size);

  /* In blocking mode, we would normally wait for transmission to complete */
  /* Since we're simulating, we can skip the hardware wait loop */

  /* Return success status */
  return HAL_OK;
}
